<?php

namespace App\Restaurant\Repository;
use DateTime;
use App\Restaurant\Entity\Particular;
use App\Restaurant\Entity\Purchase;
use App\Restaurant\Entity\PurchaseItem;
use Doctrine\ORM\EntityRepository;
use App\Tool\Entity\GlobalOption;


/**
 * PurchaseRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class PurchaseRepository extends EntityRepository
{

    protected function handleSearchBetween($qb,$data)
    {
        $startDate = $data['startDate'] ?? '';
        $endDate = $data['endDate'] ?? '';

        if (!empty($startDate) ) {
            $datetime = new DateTime($data['startDate']);
            $start = $datetime->format('Y-m-d 00:00:00');
            $qb->andWhere("e.created >= :startDate")->setParameter('startDate', $start);
        }
        if (!empty($endDate)) {
            $datetime = new DateTime($data['endDate']);
            $end = $datetime->format('Y-m-d 23:59:59');
            $qb->andWhere("e.created <= :endDate")->setParameter('endDate', $end);
        }
    }

    public function updatePurchaseTotalPrice(Purchase $entity)
    {
        $em = $this->_em;
        $total = $em->createQueryBuilder()
            ->from(\App\Restaurant\Entity\PurchaseItem::class,'si')
            ->select('sum(si.purchaseSubTotal) as total')
            ->where('si.purchase = :entity')
            ->setParameter('entity', $entity ->getId())
            ->getQuery()->getSingleResult();

        if($total['total'] > 0){

            $entity->setSubTotal($total['total']);
            $entity->setNetTotal($entity->getSubTotal() - $entity->getDiscount());
            $entity->setDue($entity->getNetTotal() - $entity->getPayment() );

        }else{

            $entity->setSubTotal(0);
            $entity->setNetTotal(0);
            $entity->setDue(0);
            $entity->setDiscount(0);
        }

        $em->persist($entity);
        $em->flush();

        return $entity;

    }

    public function purchaseTransactionReverse(Purchase $entity){

        $em = $this->_em;
        $accountCash = $em->createQuery("DELETE AccountingBundle:AccountPurchase e WHERE e.restaurantPurchase = {$entity->getId()}");
        if(!empty($accountCash)){
            $accountCash->execute();
        }

    }

    public function reversePurchaseParticularUpdate(Purchase $invoice)
    {
        $em = $this->_em;

        /** @var PurchaseItem $item */
        foreach($invoice->getPurchaseItems() as $item ){
            /** @var Particular  $particular */
            $particular = $item->getParticular();
            $qnt = ($particular->getPurchaseQuantity() - $item->getQuantity());
            $particular->setPurchaseQuantity($qnt);
            $em->persist($particular);
            $em->flush();
            $em->getRepository(\App\Restaurant\Entity\Particular::class)->remainingQnt($particular);
        }
    }

    public function androidDevicePurchaseOverview(GlobalOption $option ,$data)
    {
        $config =  $option->getRestaurantConfig()->getId();
        $qb = $this->createQueryBuilder('e');
        $qb->select('sum(e.netTotal) as total ,sum(e.payment) as payment');
        $qb->where('e.restaurantConfig = :config');
        $qb->setParameter('config', $config);
        $qb->andWhere('e.process = :process');
        $qb->setParameter('process', 'approved');
        $this->handleSearchBetween($qb,$data);
        return $qb->getQuery()->getOneOrNullResult();

    }


}
